import bench, mujoco, numpy as np
seeds=[0]
mref,tref,sref = bench.ref(seeds=seeds)
base = open('model_ref.xml').read().replace('<compiler autolimits=\"true\"/>', '<compiler autolimits=\"true\"/>\n  <option %s/>')
for ts in [0.002,0.004,0.008]:
  for integ in ['Euler','implicit','implicitfast','RK4']:
    xml = base % f'timestep=\"{ts}\" integrator=\"{integ}\"'
    try:
        m,t,s = bench.bench(xml, seeds=seeds)
        print(ts, integ, round(t.mean(),4), 'diff %.3e'%np.linalg.norm(s-sref), np.allclose(s,sref,atol=1e-5))
    except Exception as e: print(ts, integ,'ERR',e)
